// F-4 fixture, pre-registered in R-475 §3(b) / AR-476.
// A **REAL** occurrence under a directory whose NAME IS IN `PRUNE_DIRS`.
// Before the R-475 repair the tool printed `1 PRESENT, 0 UNREADABLE, of 1` ·
// ADMISSIBLE · exit 0 over this tree, and THIS FILE APPEARED NOWHERE -- not
// excluded, not unreadable, not listed. The true count was 2.
// The fixture is the PAIR: undeclared -> non-zero naming this directory;
// declared -> exit 0 with this exact path EMITTED and the proposition narrowed.
import { writeFileSync } from "fs";
export function buried(p: string, d: string): void { writeFileSync(p, d); }
